Q: How can I resolve the error &quot;the expected type comes from property &#39;component&#39; which is declared here on type&quot;? A: <p>you haven't returned the JSX for Enter Account component that is why you are getting the error, add return statement in that component</p>
<pre><code>import React from 'react';
import { View, Text, StyleSheet } from 'react-native';

const EnterAccount = (props: any) =&gt;  {
  return (
    &lt;View style={styles.screen}&gt;
        &lt;Text&gt;
            Enter Account Screen
        &lt;/Text&gt;
    &lt;/View&gt;
  )
}

const styles = StyleSheet.create({
    screen: {
        flex: 1,
        justifyContent: 'center',
        alignItems: 'center',
    }
})

export default EnterAccount;
</code></pre>
